void *const *rt::vtable(rt::u32 address)
{
    switch (address) {
    case 0x800908ec: return kVt_ScreenViewLoop;
    case 0x800906c8: return kVt_psxViewLoop;
    case 0x80090630: return kVt_psxViewLoopDoubleBuffer;
    case 0x80011d40: return kVt_VendorBootLogo;
    case 0x8001156c: return kVt_psxMovieLoop;
    case 0x8005a7fc: return kVt_QuickMenu;
    case 0x8005a7b4: return kVt_PreQuickMenuIO;
    case 0x8002ef98: return kVt_RaceViewLoop;
    case 0x8002ef58: return kVt_RaceMenuLoop;
    case 0x8002f000: return kVt_ArcadeRaceLoop;
    case 0x8002f110: return kVt_RaceLoop;
    case 0x8002106c: return kVt_BaseMenu;
    case 0x80026fb8: return kVt_ArcadeMenu;
    case 0x80027010: return kVt_ArcadeRacingMenu;
    case 0x80022ca4: return kVt_GTMenu;
    case 0x80022c5c: return kVt_GTLoadingMenu;
    case 0x80022d04: return kVt_GTBattleMenu;
    }
    Rt_Fatal("no vtable %08x", address);
}
